"""Real recordings of the scripted calls (generated by ``tools/gen_call_audio.py``), used by the live "via audio" path.

A scripted call is normally replayed as the channel's native transcript. "Via audio" instead sends the *recording* of the
call through speech-to-text. With the mock transcriber the call is looked up by fixture id; with Azure Speech the audio
itself is transcribed, so a placeholder silent WAV would be useless: when a real recording exists it is used.
"""
from __future__ import annotations

from pathlib import Path

from pydantic import Field

from ...domain.base import VModel
from ..transcription.wav import read_wav_info

AUDIO_EXTENSIONS = (".wav", ".mp3", ".m4a", ".ogg", ".webm")
_CONTENT_TYPES = {".wav": "audio/wav", ".mp3": "audio/mpeg", ".m4a": "audio/mp4", ".ogg": "audio/ogg", ".webm": "audio/webm"}


class RecordingInfo(VModel):
    path: Path
    content_type: str
    bytes: int
    seconds: float | None = Field(default=None, description="known for WAV files")
    channels: int | None = None


def find_recording(fixture_id: str, directory: Path | str | None) -> RecordingInfo | None:
    """The recording for a scripted call (``<directory>/<fixture_id>.<ext>``), or None. Never reads outside ``directory``."""
    if not directory or not fixture_id or any(sep in fixture_id for sep in ("/", "\\", "..")):
        return None
    base = Path(directory)
    for ext in AUDIO_EXTENSIONS:
        path = base / f"{fixture_id}{ext}"
        if path.is_file():
            wav = read_wav_info(path) if ext == ".wav" else None
            return RecordingInfo(path=path, content_type=_CONTENT_TYPES[ext], bytes=path.stat().st_size,
                                 seconds=round(wav.duration_seconds, 1) if wav else None, channels=wav.channels if wav else None)
    return None
